select tfo.id, tfo.code, tfo.transfer_direction, tfo.approve_status, tfo.invalid_status, tod.sku_id, tod.sku_no, tfo.bill_date, tod.qty, tod.unit, tfo.out_warehouse_id, tfo.out_warehouse_name, tod.remark, tfo.approve_user_name, tfo.create_user_name, tfo.create_time, tod.out_warehouse_location from transfer_out tfo inner join transfer_out_detail tod on tfo.id = tod.main_id and tod.is_deleted = false
tfo.is_deleted = false
and tfo.code ilike concat('%',#{params.code},'%')
and tfo.invalid_status = #{params.invalidStatus}
and tfo.transfer_direction = #{params.transferDirection}
and tod.sku_no in
#{item}
and tfo.approve_status in
#{item}
and tfo.out_warehouse_id in
#{item}
and tfo.create_user_id in
#{item}
and tfo.create_time >= #{params.createTimeList[0]} and (#{params.createTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > tfo.create_time
and tfo.bill_date >= #{params.billDateList[0]} and (#{params.billDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > tfo.bill_date
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
tfo.id desc,tod.id desc

